        {
          "en": "If old buildings are not renovated, structural and hygiene problems may worsen.",
          "zh": "如果舊樓沒有翻新，結構和衛生問題可能惡化。"
        },
        {
          "en": "Renovating old buildings can improve safety while preserving community character.",
          "zh": "翻新舊樓可以改善安全，同時保留社區特色。"
        }
