        {
          "en": "Economic growth can create jobs and raise living standards.",
          "zh": "經濟增長可以創造職位並提高生活水平。"
        },
        {
          "en": "Economic growth means an increase in the value of goods and services produced by an economy.",
          "zh": "經濟增長是指一個經濟體所生產的商品和服務價值增加。"
        },
        {
          "en": "A city may experience economic growth when more businesses open and more people are employed.",
          "zh": "當更多企業開業、更多人受僱，一個城市可能出現經濟增長。"
        },
        {
          "en": "Strong economic growth can increase government revenue and support public services.",
          "zh": "強勁經濟增長可以增加政府收入，並支援公共服務。"
        },
        {
          "en": "Economic growth is more meaningful when ordinary people also benefit from better wages and opportunities.",
          "zh": "當普通市民也能得到更好工資和機會，經濟增長才更有意義。"
        }
